package com.revivex.service; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Component; import javax.crypto.Mac; import javax.crypto.spec.SecretKeySpec; import java.nio.charset.StandardCharsets; import java.security.MessageDigest; import java.util.HexFormat; @Component public class WebhookSecurity { private final String secret; public WebhookSecurity(@Value("${revivex.razorpay.webhook-secret:}")String secret){this.secret=secret;} public boolean verify(String body,String signature){if(secret==null||secret.isBlank())return false;try{Mac mac=Mac.getInstance("HmacSHA256");mac.init(new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8),"HmacSHA256"));String expected=HexFormat.of().formatHex(mac.doFinal(body.getBytes(StandardCharsets.UTF_8)));return MessageDigest.isEqual(expected.getBytes(StandardCharsets.UTF_8),signature.getBytes(StandardCharsets.UTF_8));}catch(Exception e){return false;}} public boolean configured(){return secret!=null&&!secret.isBlank();} }
